#!/bin/bash# kds-kiosk.sh — Orange Pi Zero 3 (Armbian XFCE) em modo quiosque para KDS Bridge## Este arquivo é o LAUNCHER do quiosque. O autostart do XFCE deve apontar para ele# (veja "AUTOSTART NO XFCE" no fim do arquivo).## Cenário: o servidor KDS roda no PC (ou nuvem) e os 2 Pis são telas quiosque# que apenas abrem o Chromium numa URL. Banco de dados = Supabase (nuvem).##   - Pi 1 (cozinha quente A/B): KDS_SCREEN="quente" -> /cozinha-quente#   - Pi 2 (cozinha fria)       : KDS_SCREEN="fria"   -> /cozinha-fria# =====================================================# CONFIGURAÇÃO — altere aqui:# =====================================================# IP do PC (ou servidor cloud) onde roda o KDS, na porta 3000.# No Windows, descubra com: ipconfig -> IPv4 do adaptador de rede.# Em produção use o domínio DuckDNS (independe da rede local) ou o IP tailnet 100.x:#   SERVER_URL="https://kds-framboa.duckdns.org"  # produção (recomendado)#   SERVER_URL="http://100.x.x.x:3000"            # tailnet Tailscale se o servidor estiver na mesma tailnetSERVER_URL="https://kds-framboa.duckdns.org"# Tela deste Orange Pi: "quente" ou "fria"KDS_SCREEN="quente"# =====================================================# A partir daqui não precisa editar (só ajustes avançados)# =====================================================# Desligar protetor de tela / suspensão de telaxset s offxset s noblankxset -dpms# Esconder o cursor do mouseunclutter -idle 0 &# Aguardar a rede estabilizar antes de abrir o navegadorsleep 5case "$KDS_SCREEN" in  quente) URL="$SERVER_URL/cozinha-quente" ;;  fria)   URL="$SERVER_URL/cozinha-fria" ;;  *)      URL="$SERVER_URL" ;;esacchromium --noerrdialogs \         --disable-infobars \         --no-first-run \         --kiosk \         --disable-session-crashed-bubble \         --disable-restore-session-state \         --user-data-dir="/tmp/chromium-kiosk" \         "$URL"# =====================================================# AUTOSTART NO XFCE (Armbian)# =====================================================# 1) Copie este script para o home do usuário e torne-o executável:#      cp orange-pi-autostart.sh ~/kds-kiosk.sh#      chmod +x ~/kds-kiosk.sh## 2) Crie o atalho de autostart do XFCE em ~/.config/autostart/kds-kiosk.desktop:#      [Desktop Entry]#      Type=Application#      Name=KDS Kiosk#      Exec=/home/SEU_USUARIO/kds-kiosk.sh#      X-GNOME-Autostart-enabled=true#    (troque SEU_USUARIO pelo usuário criado no primeiro boot do Armbian)## 3) PRIMEIRA VEZ — antes de confiar no quiosque: abra o Chromium manualmente,#    vá em http://SEU_PC_IP:3000/cozinha-quente (ou /cozinha-fria), faça login#    com a conta de papel "cozinha". O token é salvo no localStorage e persiste#    após reiniciar, então o quiosque não pede login de novo.## 4) Pacotes necessários (instale uma vez):#      sudo apt update && sudo apt install -y chromium unclutter# =====================================================